// /enterprise — Meeticulous Enterprise landing page.
//
// This is the ported "enterprise-landing" design (React/Vite standalone) dropped
// into the app. Everything visual lives under enterprise-v2/. ALL of the design's
// CSS is scoped under `.ent-lp` (enterprise.scoped.css, auto-generated by
// scratchpad/scope-css.cjs) so its hand-rolled utility classes (.flex, .text-xl,
// .rounded-2xl, …) never collide with the app's real Tailwind on other routes.
//
// The global Navbar + Footer still wrap this route (App.jsx renders them; this
// route is intentionally NOT in App.jsx's hideNavbar list) — so this file owns
// only the page body + SEO.
import Seo from '../components/common/Seo';
import { ogCard } from '../config/ogImages';
import { ENT_SEO, buildEnterpriseJsonLd } from './enterprise-v2/seo';
import './enterprise-v2/enterprise.scoped.css';

import { ScrollProgress } from './enterprise-v2/components/ScrollProgress';
import { Hero } from './enterprise-v2/components/Hero';
import { FeatureHighlights } from './enterprise-v2/components/FeatureHighlights';
import { SolutionsTabs } from './enterprise-v2/components/SolutionsTabs';
import { Workflow } from './enterprise-v2/components/Workflow';
import { Industries } from './enterprise-v2/components/Industries';
import { Support } from './enterprise-v2/components/Support';
import { Integrations } from './enterprise-v2/components/Integrations';
import { Deployment } from './enterprise-v2/components/Deployment';
import { Timeline } from './enterprise-v2/components/Timeline';
import { FAQ } from './enterprise-v2/components/FAQ';
import { EnterpriseForm } from './enterprise-v2/components/EnterpriseForm';
import { CTASection } from './enterprise-v2/components/CTASection';

export default function Enterprise() {
  return (
    <div className="ent-lp">
      <Seo
        title={ENT_SEO.title}
        description={ENT_SEO.description}
        canonical={ENT_SEO.canonical}
        keywords={ENT_SEO.keywords}
        ogTitle={ENT_SEO.ogTitle}
        ogDescription={ENT_SEO.ogDescription}
        image={ogCard('enterprise')}
        jsonLd={buildEnterpriseJsonLd()}
      />

      <ScrollProgress />
      <main>
        <Hero />
        <FeatureHighlights />
        <SolutionsTabs />
        <Workflow />
        <Industries />
        <Support />
        <Integrations />
        <Deployment />
        <Timeline />
        <FAQ />
        <EnterpriseForm />
        <CTASection />
      </main>
    </div>
  );
}
